# -*- coding: utf-8 -*-
import sys

def main():
    data = sys.stdin.read().strip().split()
    n, k = map(int, data)

    if k == 0:
        # k=0，输出升序
        print("YES")
        print(*range(1, n+1))
    elif k == -1:
        # k=-1，交替出两端
        print("YES")
        L, R = 1, n
        res = []
        for i in range(1, n+1):
            if i % 2 == 1:
                res.append(L)
                L += 1
            else:
                res.append(R)
                R -= 1
        print(*res)
    elif k == 1:
        # k=1，先构造 k=-1，再逆序
        L, R = 1, n
        res = []
        for i in range(1, n+1):
            if i % 2 == 1:
                res.append(L)
                L += 1
            else:
                res.append(R)
                R -= 1
        res.reverse()
        print("YES")
        print(*res)
    else:
        # 其他情况无解
        print("NO")

if __name__ == "__main__":
    main()
